/* ============================================================
   REPORT STYLE SYSTEM — single file · offline · no JS · system fonts
   Layers: 1 tokens · 2 base · 3 layout · 4 components · 5 utilities · 6 print
   Rule: editors change layer 1 only; components consume tokens.
   ============================================================ */

/* ---- 1 · DESIGN TOKENS — every visual decision lives here ---- */
:root {
  /* Color roles. Text pairs chosen for WCAG AA; status colors always
     appear with a text label, never color alone. */
  --paper:   #ffffff;   /* page background */
  --ink:     #1a2332;   /* primary text */
  --muted:   #56677c;   /* secondary text */
  --line:    #d7dee8;   /* hairlines, table borders */
  --surface: #f4f6f9;   /* tiles, table header fill */
  --accent:  #1f4e79;   /* brand: h1, h2 rule, links */
  --ok:      #2e7d32;   /* status: green / on track */
  --warn:    #9a5b00;   /* status: amber / at risk */
  --alert:   #b3261e;   /* status: red / off track */
  --draft:   #fff8d6;   /* unfilled placeholder */

  /* Type scale — rem only, ~1.22 ratio */
  --text-2: 1.65rem;    /* h1 */
  --text-1: 1.15rem;    /* h2 */
  --text-0: 1rem;       /* body */
  --text--1: .92rem;    /* tables, dense data */
  --text--2: .8rem;     /* micro labels, footer */

  /* Space scale — 4px base */
  --s1: .25rem; --s2: .5rem; --s3: .75rem; --s4: 1rem;
  --s6: 1.5rem; --s8: 2rem; --s12: 3rem;

  /* Layout constants */
  --measure: 60rem;     /* line-length ceiling (~75ch) */
  --leading: 1.5;
  --radius: .4rem;
}

/* ---- 2 · BASE — reset + typography defaults ---- */
* { box-sizing: border-box; }
body {
  font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--ink); background: var(--paper);
  font-size: var(--text-0); line-height: var(--leading);
  margin: 0; padding: var(--s8) var(--s4);
}
h1, h2, h3 { line-height: 1.25; }
h1 { font-size: var(--text-2); color: var(--accent); margin: 0 0 var(--s2); }
h2 { font-size: var(--text-1); margin: var(--s8) 0 var(--s3);
     border-bottom: 2px solid var(--accent); padding-bottom: var(--s1); }
h3 { font-size: var(--text-0); margin: var(--s4) 0 var(--s1); }
p, ul, ol, dl, table { margin: 0 0 var(--s3); }
a { color: var(--accent); }
a:hover { text-decoration-thickness: 2px; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* ---- 3 · LAYOUT — one column, measure-limited, header/main/footer ---- */
header, main, footer, nav { max-width: var(--measure); margin-inline: auto; }
header { border-bottom: 3px solid var(--accent); padding-bottom: var(--s4); }
footer { border-top: 1px solid var(--line); margin-top: var(--s12);
         padding-top: var(--s3); }
nav ol { font-size: var(--text--1); columns: 2; gap: var(--s6);
         padding-left: var(--s4); margin-top: var(--s4); }

/* ---- 4 · COMPONENTS ---- */

/* Metadata list (header): tight two-column label/value grid */
dl.meta { display: grid; grid-template-columns: max-content 1fr;
          gap: var(--s1) var(--s4); margin: var(--s4) 0 0; }
dl.meta dt { font-weight: 600; color: var(--muted); }
dl.meta dd { margin: 0; }
address { font-style: normal; }

/* Status badges — token swap recolors, text label is the source of truth */
.rag { display: inline-block; min-width: 5.5ch; text-align: center;
       font-weight: 600; font-size: var(--text--2); color: #fff;
       padding: var(--s1) var(--s2); border-radius: 1rem; }
.rag-green { background: var(--ok); }
.rag-amber { background: var(--warn); }
.rag-red   { background: var(--alert); }

/* Dashboard tiles: auto-fit grid, 1→n columns, no media queries needed */
.tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
         gap: var(--s2); list-style: none; padding: 0; }
.tiles li { border: 1px solid var(--line); border-radius: var(--radius);
            background: var(--surface); padding: var(--s2) var(--s3); }
.tiles h3 { margin: 0; font-size: var(--text--2); text-transform: uppercase;
            letter-spacing: .04em; color: var(--muted); }
.tiles p { margin: var(--s1) 0 0; font-weight: 600; }

/* Data tables: full-width hairline grid, tinted header */
table { border-collapse: collapse; width: 100%; font-size: var(--text--1); }
caption { caption-side: top; text-align: left; font-style: italic;
          color: var(--muted); padding-bottom: var(--s1);
          font-size: var(--text--2); }
th, td { border: 1px solid var(--line); padding: var(--s2) var(--s2);
         text-align: left; vertical-align: top; }
thead th { background: var(--surface); }
tbody tr:nth-child(even) { background: color-mix(in srgb, var(--surface) 55%, white); }
meter { width: 100%; height: .9rem; }

/* Emphasis paragraphs (plan-vs-actual, changes, resources) */
p strong { color: var(--accent); }

/* ---- 5 · UTILITIES ---- */
.lede { color: var(--muted); font-size: var(--text--1); margin: 0; }
.placeholder { background: var(--draft); outline: 1px dashed var(--warn);
               padding: 0 var(--s1); }

/* ---- 6 · PRINT — A4/Letter: ink-saver, no split content ---- */
@media print {
  body { padding: 0; font-size: 10.5pt; }
  nav { display: none; }                    /* TOC redundant on paper */
  section, table, .tiles li { break-inside: avoid; }
  h2 { break-after: avoid; }
  a { text-decoration: none; color: inherit; }
  .placeholder { background: none; outline: none; }
  tbody tr:nth-child(even) { background: var(--surface); }
}
